// Static viewer for the Saltmere Sprawl demo world. Data comes from data.js (generated by
// scripts/exportDemoSnapshot.js); there is no network access and no backend. Hash routes:
//   #/                 hub (category cards)
//   #/<category>       entry grid
//   #/<category>/<id>  dossier
(function () {
  var D = window.DEMO_DATA;
  var view = document.getElementById('view');
  if (!D) { view.innerHTML = '<p>Demo data failed to load.</p>'; return; }

  var HEX = /^#[0-9a-fA-F]{6}$/;
  function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }

  // World theme -- same CSS-variable overrides the app applies from the world's style guide.
  (function applyTheme() {
    var t = D.world.theme || {}, o = [];
    if (HEX.test(t.backgroundColor)) o.push('--bg-void:' + t.backgroundColor);
    if (HEX.test(t.panelColor)) o.push('--bg-panel:' + t.panelColor, '--bg-panel-raised:' + t.panelColor);
    if (HEX.test(t.inkColor)) o.push('--ink:' + t.inkColor);
    if (HEX.test(t.primaryColor)) o.push('--neon-primary:' + t.primaryColor);
    if (HEX.test(t.secondaryColor)) o.push('--neon-cyan:' + t.secondaryColor);
    if (t.fontDisplay) o.push("--font-display:'" + t.fontDisplay + "',sans-serif");
    if (t.fontBody) o.push("--font-body:'" + t.fontBody + "',sans-serif");
    var s = document.createElement('style'); s.textContent = ':root{' + o.join(';') + '}'; document.head.appendChild(s);
  })();

  var catBySlug = {}; D.categories.forEach(function (c) { catBySlug[c.slug] = c; });
  document.getElementById('site-title-link').textContent = D.world.title;
  document.getElementById('demo-footer').textContent = D.world.footer || 'CHRONICLED';
  document.getElementById('site-nav').innerHTML = D.categories.map(function (c) { return '<a href="#/' + c.slug + '" data-cat="' + c.slug + '">' + esc(c.label) + '</a>'; }).join('');

  function facColor(key) { var f = key && D.factions[key]; return f && f.accent ? f.accent : 'var(--neon-cyan)'; }
  function facTag(key) { var f = key && D.factions[key]; return f ? '<span class="tag fac">' + esc(f.name) + '</span>' : ''; }
  function entriesIn(slug) { return D.entries.filter(function (e) { return e.category === slug; }).sort(function (a, b) { return a.name.localeCompare(b.name); }); }

  function card(e) {
    return '<div class="entry-card" style="--fac-color:' + facColor(e.faction) + ';">' +
      (e.image ? '<img class="thumb" src="' + esc(e.image) + '" alt="" loading="lazy">' : '') +
      '<h3>' + esc(e.name) + '</h3><p class="role">' + esc(e.subtitle) + '</p>' +
      '<div class="tags">' + facTag(e.faction) + (e.tags || []).join('') + '</div>' +
      '<a class="card-link" href="#/' + e.category + '/' + encodeURIComponent(e.id) + '" aria-label="' + esc(e.name) + '"></a></div>';
  }

  function setActive(slug) {
    document.querySelectorAll('#site-nav a').forEach(function (a) { a.classList.toggle('active', a.getAttribute('data-cat') === slug); });
  }
  function setTitle(t) { document.title = t + ' — Demo World · Chronicled'; }

  function hub() {
    setActive(null); setTitle(D.world.name);
    var w = D.world;
    view.innerHTML =
      '<section class="demo-hero"><h1>' + esc(w.title) + '</h1>' +
      (w.statusLine ? '<p class="status">' + esc(w.statusLine) + '</p>' : '') +
      (w.tagline ? '<p class="tagline">' + esc(w.tagline) + '</p>' : '') +
      '<p class="meta">' + esc(w.name) + ' · ' + esc([].concat(w.genre || []).join(' / ')) + (w.era ? ' · ' + esc(w.era) : '') + ' · ' + D.entries.length + ' entries</p></section>' +
      '<div class="hub-grid">' + D.categories.map(function (c) {
        return '<div class="category-card"><h2>' + esc(c.label) + '</h2><p>' + esc(c.blurb) + '</p><span class="count">' + c.count + ' entr' + (c.count === 1 ? 'y' : 'ies') + '</span><a class="card-link" href="#/' + c.slug + '" aria-label="' + esc(c.label) + '"></a></div>';
      }).join('') + '</div>';
  }

  function category(slug) {
    var c = catBySlug[slug]; if (!c) return notFound();
    setActive(slug); setTitle(c.label);
    view.innerHTML = '<div class="crumb"><a href="#/">Archive</a><span class="sep">/</span><span>' + esc(c.label) + '</span></div>' +
      '<h1 style="font-family:var(--font-display);text-transform:uppercase;margin:20px 0 8px;">' + esc(c.label) + '</h1>' +
      '<p style="color:var(--ink-dim);max-width:640px;margin:0 0 24px;">' + esc(c.blurb) + '</p>' +
      '<div class="entry-grid">' + entriesIn(slug).map(card).join('') + '</div>';
  }

  function dossier(slug, id) {
    var list = entriesIn(slug), i = list.findIndex(function (e) { return e.id === id; });
    if (i < 0) return notFound();
    var e = list[i], c = catBySlug[slug];
    setActive(slug); setTitle(e.name);
    var prev = list[i - 1], next = list[i + 1];
    view.innerHTML =
      '<div class="crumb"><a href="#/">Archive</a><span class="sep">/</span><a href="#/' + slug + '">' + esc(c.label) + '</a><span class="sep">/</span><span>' + esc(e.name) + '</span></div>' +
      '<div class="sheet" style="--fac-color:' + facColor(e.faction || (slug === 'factions' ? e.id : null)) + ';">' +
        (e.banner ? '<img class="faction-banner" src="' + esc(e.banner) + '" alt="">' : '') +
        '<div class="sheet-header"><p class="sheet-eyebrow">' + esc(e.eyebrow) + '</p><h1>' + esc(e.name) + '</h1>' +
        '<p class="subtitle">' + esc(e.subtitle) + '</p><div>' + facTag(e.faction) + (e.tags || []).join('') + '</div></div>' +
        '<div class="sheet-body">' + e.bodyHtml + '</div>' +
        (e.footer && e.footer.length ? '<div class="sheet-footer">' + e.footer.filter(function (f) { return !/generated via Chronicled/i.test(f); }).map(function (f) { return '<span>' + esc(f) + '</span>'; }).join('') + '<span>Demo snapshot — read-only</span></div>' : '') +
      '</div>' +
      '<div class="sheet-nav"><span>' + (prev ? '<a href="#/' + slug + '/' + encodeURIComponent(prev.id) + '">← ' + esc(prev.name) + '</a>' : '') + '</span><span>' + (next ? '<a href="#/' + slug + '/' + encodeURIComponent(next.id) + '">' + esc(next.name) + ' →</a>' : '') + '</span></div>' +
      '<div class="demo-end-cta"><h2>Make an archive like this for your world</h2><p>Describe your world once; Chronicled generates entries grounded in it and files them here automatically.</p><a class="demo-cta" href="https://app.chronicled.world/">Start Now</a></div>';
  }

  function notFound() { setActive(null); setTitle('Not found'); view.innerHTML = '<p style="margin:60px 0;color:var(--ink-dim);">That page isn’t in the demo. <a href="#/">Back to the archive</a>.</p>'; }

  function route() {
    var parts = (location.hash || '#/').replace(/^#\/?/, '').split('/').filter(Boolean).map(decodeURIComponent);
    closeSearch();
    if (!parts.length) hub(); else if (parts.length === 1) category(parts[0]); else dossier(parts[0], parts.slice(1).join('/'));
    window.scrollTo(0, 0);
  }
  window.addEventListener('hashchange', route);

  // Search: name substring across all categories, grouped like the app's search dropdown.
  var input = document.getElementById('demo-search'), box = document.getElementById('demo-search-results');
  function closeSearch() { box.hidden = true; box.innerHTML = ''; }
  input.addEventListener('input', function () {
    var q = input.value.trim().toLowerCase(); if (!q) return closeSearch();
    var html = D.categories.map(function (c) {
      var hits = entriesIn(c.slug).filter(function (e) { return e.name.toLowerCase().indexOf(q) !== -1; }).slice(0, 6);
      return hits.length ? '<div class="site-search-group"><div class="site-search-group-label">' + esc(c.label) + '</div>' + hits.map(function (e) { return '<a class="site-search-result" href="#/' + c.slug + '/' + encodeURIComponent(e.id) + '"><span>' + esc(e.name) + '</span></a>'; }).join('') + '</div>' : '';
    }).join('');
    box.innerHTML = html || '<div class="site-search-empty">No matches.</div>'; box.hidden = false;
  });
  document.addEventListener('click', function (ev) { if (!ev.target.closest('.demo-search')) closeSearch(); });
  input.addEventListener('keydown', function (ev) { if (ev.key === 'Escape') { input.value = ''; closeSearch(); } });

  route();
})();
